window.KHO_DATA_L4_GDTC = [
{"lop":4,"mon":"Giáo dục thể chất","tuan":1,"tiet":1,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 1: Biến đổi đội hình từ một hàng dọc thành hai, ba hàng dọc và ngược lại (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết khẩu lệnh và thực hiện được cách biến đổi đội hình từ một hàng dọc thành hai, ba hàng dọc theo điểm số; giữ được cự li, hàng lối thẳng, đều.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Thể hiện sự nghiêm túc, kỉ luật khi tập hợp và di chuyển đội hình.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu, khăn/vật đánh dấu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện biến đổi đội hình từ một hàng dọc thành hai, ba hàng dọc.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: Lớp tập hợp một hàng dọc, điểm số theo chu kì 1–2 (hoặc 1–2–3).\n+ Theo khẩu lệnh, các số chẵn (số 2, số 3) bước chếch sang ngang một bước để tạo thành hai (ba) hàng dọc; khi có lệnh về đội hình ban đầu thì các em bước về vị trí cũ.\n+ GV nhắc HS giữ cự li, thẳng hàng, quay – bước dứt khoát.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là cách biến đổi đội hình từ một hàng dọc thành hai, ba hàng dọc theo điểm số.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn biến đổi đội hình một – hai – ba hàng dọc.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":1,"tiet":2,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 1: Biến đổi đội hình từ một hàng dọc thành hai, ba hàng dọc và ngược lại (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Củng cố, thực hiện thành thạo biến đổi đội hình một – hai – ba hàng dọc và ngược lại; phối hợp nhịp nhàng trong tổ, nhóm.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Đoàn kết, hợp tác trong tổ để đội hình đều, đẹp.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện biến đổi đội hình từ một hàng dọc thành hai, ba hàng dọc và ngược lại (ôn luyện).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV nhắc lại yếu lĩnh, hô khẩu lệnh cho cả lớp thực hiện biến đổi đội hình.\n+ Chia tổ luyện tập; tổ trưởng điều khiển tổ biến đổi đội hình và về đội hình ban đầu.\n+ GV sửa sai về cự li, hàng lối, hướng bước.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Khi biến đổi cần giữ thẳng hàng, đúng cự li và bước dứt khoát.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn biến đổi và khôi phục đội hình hàng dọc.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":2,"tiet":1,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 2: Biến đổi đội hình từ một hàng ngang thành hai, ba hàng ngang và ngược lại (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết khẩu lệnh và thực hiện được biến đổi đội hình từ một hàng ngang thành hai, ba hàng ngang theo điểm số; giữ cự li, thẳng hàng.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện biến đổi đội hình từ một hàng ngang thành hai, ba hàng ngang.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: Lớp tập hợp một hàng ngang, điểm số theo chu kì.\n+ Theo khẩu lệnh, các số quy định bước tiến/lùi để tạo thành hai (ba) hàng ngang; khi có lệnh thì trở về một hàng ngang.\n+ GV nhắc giữ cự li, giãn cách, thẳng hàng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là biến đổi đội hình một hàng ngang thành hai, ba hàng ngang theo điểm số.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn biến đổi đội hình một – hai – ba hàng ngang.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":2,"tiet":2,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 2: Biến đổi đội hình từ một hàng ngang thành hai, ba hàng ngang và ngược lại (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện thành thạo biến đổi đội hình hàng ngang; phối hợp linh hoạt giữa đội hình hàng dọc và hàng ngang.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ, khăn; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện biến đổi đội hình hàng ngang và ngược lại (ôn luyện, phối hợp).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho cả lớp ôn biến đổi đội hình hàng ngang, kết hợp ôn biến đổi hàng dọc đã học.\n+ Luyện tập theo tổ, tổ trưởng điều khiển; thi đua giữa các tổ về độ nhanh, đều, thẳng hàng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Cần giữ thẳng hàng, đúng cự li khi biến đổi và khôi phục đội hình.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn phối hợp biến đổi đội hình hàng dọc và hàng ngang.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Cướp cờ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia hai đội, đặt khăn/cờ ở giữa sân, mỗi em mang số.\n+ Cách chơi: GV gọi số, hai em cùng số chạy lên cướp cờ mang về vạch của đội mình; ai mang được cờ về an toàn ghi điểm cho đội.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":3,"tiet":1,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 3: Động tác di chuyển vòng phải, vòng trái (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết khẩu lệnh và thực hiện được động tác di chuyển vòng phải, vòng trái khi đi đều; giữ nhịp bước và hàng lối.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác di chuyển vòng (chuyển hướng) sang phải, sang trái khi đi.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: Đi đều theo hàng.\n+ Khẩu lệnh \"Vòng bên phải (trái)... bước!\": người ở đầu hàng làm trụ chuyển hướng, cả hàng đi vòng theo, giữ đều nhịp bước và cự li.\n+ GV hô nhịp chậm, hướng dẫn giữ hàng lối khi chuyển hướng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là động tác di chuyển vòng phải, vòng trái khi đi đều.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn di chuyển vòng phải, vòng trái khi đi đều.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":3,"tiet":2,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 3: Động tác di chuyển vòng phải, vòng trái (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện thành thạo di chuyển vòng phải, vòng trái; phối hợp đi đều theo đội hình vòng, đảm bảo trật tự, an toàn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng nhỏ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện di chuyển vòng phải, vòng trái (ôn luyện, đi đều vòng).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho cả lớp ôn di chuyển vòng phải, vòng trái theo hàng.\n+ Luyện tập theo tổ đi đều vòng quanh sân; tổ trưởng điều khiển, GV sửa sai nhịp bước, hàng lối.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Khi vòng cần giữ đều nhịp bước, thẳng hàng và đúng cự li.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn đi đều vòng theo đội hình tổ.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":4,"tiet":1,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 4: Ôn tập, phối hợp đội hình đội ngũ (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Phối hợp thành thạo các nội dung đội hình đội ngũ đã học; điều khiển được tổ, nhóm tập luyện.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ, khăn; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện phối hợp các nội dung đội hình đội ngũ đã học (tập hợp, điểm số, biến đổi đội hình, di chuyển vòng).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV hệ thống các nội dung: tập hợp hàng dọc/ngang, điểm số, biến đổi đội hình, di chuyển vòng.\n+ Cả lớp thực hiện liên hoàn các nội dung theo khẩu lệnh của GV và cán sự.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Các nội dung đội hình đội ngũ giúp lớp di chuyển trật tự, đẹp và an toàn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn liên hoàn các nội dung đội hình đội ngũ.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Cướp cờ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia hai đội, đặt khăn/cờ ở giữa sân, mỗi em mang số.\n+ Cách chơi: GV gọi số, hai em cùng số chạy lên cướp cờ mang về vạch của đội mình; ai mang được cờ về an toàn ghi điểm cho đội.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":4,"tiet":2,"bai":"Chủ đề 1: Đội hình đội ngũ — Bài 4: Ôn tập, phối hợp đội hình đội ngũ (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng các nội dung đội hình đội ngũ vào hoạt động tập thể của nhà trường; giữ nề nếp, kỉ luật.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện phối hợp đội hình đội ngũ, vận dụng vào tập hợp – chào cờ – xếp hàng ra vào lớp.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho các tổ thi đua trình diễn liên hoàn đội hình đội ngũ.\n+ Liên hệ vận dụng khi tập hợp, chào cờ, xếp hàng ra vào lớp, thể dục giữa giờ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Vận dụng đội hình đội ngũ giúp em giữ trật tự, kỉ luật trong sinh hoạt tập thể.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trình diễn đội hình đội ngũ theo tổ.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":5,"tiet":1,"bai":"Chủ đề 2: Bài tập thể dục — Bài 1: Động tác vươn thở, động tác tay với vòng (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác vươn thở và động tác tay với vòng đúng hướng, đúng nhịp; biết phối hợp thở với động tác.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Hình thành thói quen tập thể dục buổi sáng để tăng cường sức khỏe.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác vươn thở và động tác tay với vòng (2 lần 8 nhịp).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác vươn thở với vòng — TTCB: đứng thẳng, hai tay cầm vòng phía trước.\n  Nhịp 1: chân trái bước sang ngang rộng bằng vai, hai tay đưa vòng sang ngang lên cao chếch chữ V, hít sâu bằng mũi.\n  Nhịp 2: hạ vòng về trước, thở ra từ từ bằng miệng.\n  Nhịp 3: như nhịp 1. Nhịp 4: về TTCB. Nhịp 5–8: như 1–4, đổi chân.\n+ Động tác tay với vòng — TTCB như trên.\n  Nhịp 1: bước chân trái sang ngang, hai tay đưa vòng ra trước.\n  Nhịp 2: đưa vòng xuống dọc thân. Nhịp 3: đưa vòng ra trước – lên cao, mắt nhìn theo vòng. Nhịp 4: về TTCB. Nhịp 5–8: đổi chân.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác vươn thở giúp điều hòa hô hấp; động tác tay phát triển cơ tay và vai.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác vươn thở và động tác tay với vòng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":5,"tiet":2,"bai":"Chủ đề 2: Bài tập thể dục — Bài 1: Động tác chân với vòng; ôn động tác vươn thở, tay (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác chân với vòng; phối hợp liên hoàn ba động tác vươn thở, tay, chân đúng nhịp.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, bóng nhỏ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác chân với vòng và liên hoàn ba động tác vươn thở – tay – chân.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác chân với vòng — TTCB: đứng thẳng, hai tay cầm vòng phía trước.\n  Nhịp 1: chân trái đưa ra sau, kiễng gót, hai tay đưa vòng ra trước – lên cao, mắt nhìn theo vòng.\n  Nhịp 2: chân trái đưa thẳng ra trước, hai tay đưa vòng ra trước – xuống dưới, chạm mũi bàn chân.\n  Nhịp 3: về nhịp 1. Nhịp 4: về TTCB. Nhịp 5–8: đổi chân.\n+ GV cho HS tập liên hoàn ba động tác vươn thở – tay – chân.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác chân phát triển cơ chân và giữ thăng bằng; ba động tác kết hợp thành bài khởi động buổi sáng.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn liên hoàn ba động tác vươn thở, tay, chân với vòng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":6,"tiet":1,"bai":"Chủ đề 2: Bài tập thể dục — Bài 2: Động tác lườn, động tác lưng – bụng với vòng (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác lườn và động tác lưng – bụng với vòng đúng biên độ, đúng nhịp; phát triển cơ lườn, cơ lưng, cơ bụng.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác lườn và động tác lưng – bụng với vòng.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác lườn với vòng — TTCB: đứng thẳng, hai tay cầm vòng.\n  Nhịp 1: bước chân trái sang ngang, hai tay đưa vòng lên cao.\n  Nhịp 2: nghiêng lườn sang trái, vòng vẫn giơ cao. Nhịp 3: về nhịp 1. Nhịp 4: về TTCB. Nhịp 5–8: nghiêng sang phải.\n+ Động tác lưng – bụng với vòng — TTCB như trên.\n  Nhịp 1: đưa vòng lên cao. Nhịp 2: gập thân, hai tay đưa vòng chạm mũi bàn chân. Nhịp 3: về nhịp 1. Nhịp 4: về TTCB. Nhịp 5–8: như 1–4.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác lườn, lưng – bụng giúp cơ thể dẻo dai, mềm mại.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác lườn và động tác lưng – bụng với vòng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":6,"tiet":2,"bai":"Chủ đề 2: Bài tập thể dục — Bài 2: Động tác toàn thân với vòng; ôn động tác lườn, lưng – bụng (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác toàn thân với vòng; phối hợp liên hoàn các động tác của bài thể dục với vòng.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, dây; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác toàn thân với vòng và liên hoàn các động tác đã học.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác toàn thân với vòng — TTCB: đứng thẳng, hai tay cầm vòng.\n  Nhịp 1: bước chân trái, khuỵu gối, đưa vòng ra trước.\n  Nhịp 2: đứng thẳng, đưa vòng lên cao, ngửa người. Nhịp 3: gập thân, đưa vòng chạm đất. Nhịp 4: về TTCB. Nhịp 5–8: đổi chân.\n+ GV cho HS tập liên hoàn các động tác đã học từ đầu chủ đề.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác toàn thân phối hợp nhiều nhóm cơ; bài thể dục với vòng giúp phát triển toàn diện.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn liên hoàn bài thể dục với vòng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":7,"tiet":1,"bai":"Chủ đề 2: Bài tập thể dục — Bài 3: Động tác nhảy và động tác điều hòa với vòng (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác nhảy và động tác điều hòa với vòng đúng nhịp; biết thả lỏng, điều hòa sau vận động.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác nhảy và động tác điều hòa với vòng.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác nhảy với vòng — TTCB: đứng thẳng, hai tay cầm vòng.\n  Nhịp 1: bật nhảy tách chân, đưa vòng lên cao. Nhịp 2: bật nhảy khép chân, hạ vòng về trước. Nhịp 3–4: như 1–2. Nhịp 5–8: như 1–4.\n+ Động tác điều hòa với vòng — TTCB như trên.\n  Nhịp 1: bước chân, hai tay đưa vòng nhẹ nhàng lên cao, hít vào. Nhịp 2: hạ vòng, thả lỏng, thở ra. Nhịp 3–4, 5–8: như trên, nhẹ nhàng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác nhảy tăng sức bật; động tác điều hòa giúp cơ thể trở lại trạng thái bình thường.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác nhảy và động tác điều hòa với vòng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":7,"tiet":2,"bai":"Chủ đề 2: Bài tập thể dục — Bài 3: Hoàn thiện bài thể dục với vòng (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện hoàn chỉnh, đúng nhịp bài thể dục với vòng; trình diễn được theo tổ, nhóm.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, dây; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện hoàn thiện và trình diễn bài thể dục phát triển chung với vòng (8 động tác).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho cả lớp tập hoàn chỉnh 8 động tác của bài thể dục với vòng theo nhịp hô/đếm nhịp.\n+ Chia tổ luyện tập và trình diễn; GV cùng HS nhận xét, đánh giá.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Bài thể dục với vòng là bài tập buổi sáng giúp cơ thể khỏe mạnh, dẻo dai.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trình diễn bài thể dục với vòng theo tổ.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":8,"tiet":1,"bai":"Chủ đề 2: Bài tập thể dục — Bài 4: Bài tập phát triển thể lực (sức nhanh, sức mạnh) (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được các bài tập phát triển sức nhanh, sức mạnh phù hợp lứa tuổi; biết lượng vận động vừa sức.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng nhỏ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện bài tập phát triển sức nhanh và sức mạnh của chân, tay.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Bài tập 1: Tại chỗ, bật trồng gối tách và chạm chân; 20–25 lần, lặp 2 lần, nghỉ hồi tĩnh 1 phút giữa các lần.\n+ Bài tập 2: Chạy tại chỗ gót chạm mông, hai tay chống hông; 25–30 lần, lặp 2 lần.\n+ GV lưu ý một số trường hợp không nên tập thể lực nặng: có bệnh về xương, tim mạch, mới phục hồi sau chấn thương.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Bài tập phát triển thể lực giúp cơ thể nhanh, mạnh hơn; cần tập vừa sức và an toàn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bài tập phát triển sức nhanh, sức mạnh.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":8,"tiet":2,"bai":"Chủ đề 2: Bài tập thể dục — Bài 4: Bài tập phát triển thể lực (sức bền, khéo léo) (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được bài tập phát triển sức bền, khéo léo; điều chỉnh nhịp thở và lượng vận động hợp lí.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cọc/vật đánh dấu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện bài tập phát triển sức bền và sự khéo léo, phối hợp vận động.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Bài tập 1: Chạy bền nhẹ nhàng tại chỗ/quanh sân kết hợp hít thở đều; tăng dần thời gian theo sức khỏe.\n+ Bài tập 2: Di chuyển luồn cọc/nhặt vật theo tín hiệu để rèn sự khéo léo và phản xạ.\n+ GV nhắc HS uống nước, nghỉ ngơi hợp lí, không gắng sức quá mức.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Sức bền và khéo léo giúp em vận động lâu, linh hoạt; cần lắng nghe cơ thể mình.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bài tập phát triển sức bền, khéo léo.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":9,"tiet":1,"bai":"ÔN TẬP GIỮA HỌC KÌ I: Đội hình đội ngũ và bài thể dục phát triển chung với vòng","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Hệ thống, củng cố và thực hiện thành thạo các nội dung, kĩ thuật đã học; tự đánh giá và điều chỉnh động tác của bản thân và bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Ôn luyện, củng cố và tự đánh giá mức độ hoàn thành các nội dung đã học ở nửa đầu học kì I; chuẩn bị tâm thế cho các nội dung tiếp theo.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, cờ hiệu, bóng nhỏ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Ôn tập, hệ thống kiến thức","gv":"- Mục tiêu: HS hệ thống, ôn luyện các nội dung đội hình đội ngũ và bài thể dục với vòng đã học từ tuần 1 đến tuần 8.\n- GV hệ thống lại các nội dung đã học: biến đổi đội hình hàng dọc/ngang, di chuyển vòng phải – vòng trái; bài thể dục 8 động tác với vòng; các bài tập phát triển thể lực.\n- GV chia lớp thành các tổ, mỗi tổ luân phiên ôn từng nội dung theo trạm; tổ trưởng điều khiển, GV quan sát và sửa sai.\n- GV cho các tổ trình diễn, tự nhận xét và nhận xét chéo giữa các tổ về mức độ đúng, đều, đẹp.","hs":"- HS ôn luyện tích cực theo hướng dẫn của GV và cán sự/tổ trưởng.\n- HS tự nhận xét, nhận xét chéo và điều chỉnh động tác; ghi nhớ những nội dung cần cải thiện."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn các nội dung, kĩ thuật đã học theo tổ, nhóm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Thi đua giữa các tổ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia lớp thành các tổ đều nhau.\n+ Cách chơi: Các tổ lần lượt trình diễn/thi đua các nội dung đã ôn; ban giám khảo (GV và cán sự) chấm theo tiêu chí đúng – đều – đẹp; tổ điểm cao nhất thắng cuộc.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":9,"tiet":2,"bai":"Chủ đề 3: Thể thao tự chọn (Đá cầu) — Bài 1: Làm quen với quả cầu và tư thế chuẩn bị (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết cách cầm cầu, tư thế chuẩn bị và tâng cầu bằng tay ở mức đơn giản; hình thành hứng thú với môn đá cầu.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Yêu thích và giữ gìn quả cầu, dụng cụ tập luyện.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện làm quen với quả cầu, cách cầm cầu và tư thế chuẩn bị trong đá cầu.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV giới thiệu quả cầu, cách cầm cầu bằng tay thuận.\n+ TTCB: đứng chân trước chân sau, gối hơi khuỵu, mắt nhìn theo cầu.\n+ Tập tung cầu và bắt cầu; tập tâng cầu bằng lòng bàn tay tại chỗ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là cách cầm cầu, tư thế chuẩn bị và tâng cầu bằng tay.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn cầm cầu, tư thế chuẩn bị và tâng cầu bằng tay.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":10,"tiet":1,"bai":"Chủ đề 3: Đá cầu — Bài 2: Tâng cầu bằng đùi (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được kĩ thuật tâng cầu bằng đùi ở mức cơ bản; phối hợp mắt – chân để giữ cầu.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật tâng cầu bằng đùi.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: đứng chân trước chân sau, một tay cầm cầu.\n+ Tung cầu lên, dùng đùi chân thuận tâng nhẹ cầu lên cao rồi bắt lại; lặp lại nhiều lần.\n+ GV hướng dẫn tiếp xúc cầu bằng phần giữa đùi, giữ thăng bằng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật tâng cầu bằng đùi.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn tâng cầu bằng đùi.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":10,"tiet":2,"bai":"Chủ đề 3: Đá cầu — Bài 2: Tâng cầu bằng đùi (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tâng cầu bằng đùi được nhiều lần liên tục hơn; phối hợp theo cặp để tâng và chuyền cầu.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá, khăn bịt mắt; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện tâng cầu bằng đùi (ôn luyện, tăng số lần).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn tâng cầu bằng đùi, đếm số lần tâng liên tục.\n+ Luyện tập theo cặp: một bạn tung, một bạn tâng; đổi vai; thi đua tâng cầu nhiều lần giữa các cặp.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Tâng cầu nhiều lần cần kiên trì luyện tập và giữ nhịp đều.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn tâng cầu bằng đùi theo cặp.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Bịt mắt bắt dê\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: HS đứng vòng tròn, chọn một bạn bịt mắt bắt dê.\n+ Cách chơi: Bạn bịt mắt di chuyển bắt bạn trong vòng theo tiếng vỗ tay; rèn sự nhanh nhẹn, khéo léo và định hướng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":11,"tiet":1,"bai":"Chủ đề 3: Đá cầu — Bài 3: Tâng cầu bằng mu bàn chân (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được kĩ thuật tâng cầu bằng mu bàn chân ở mức cơ bản; giữ thăng bằng khi tâng cầu.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật tâng cầu bằng mu bàn chân.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: đứng chân trước chân sau, tay cầm cầu.\n+ Tung cầu, dùng mu bàn chân thuận tâng nhẹ cầu lên rồi bắt lại; chú ý cổ chân thả lỏng, tiếp xúc đúng mu bàn chân.\n+ GV làm mẫu chậm, sửa sai cho HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật tâng cầu bằng mu bàn chân.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn tâng cầu bằng mu bàn chân.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":11,"tiet":2,"bai":"Chủ đề 3: Đá cầu — Bài 3: Phối hợp tâng cầu bằng đùi và mu bàn chân (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Phối hợp được tâng cầu bằng đùi và mu bàn chân; tăng số lần tâng cầu liên tục.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá, khăn; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện phối hợp tâng cầu bằng đùi và mu bàn chân.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn hai kĩ thuật, sau đó phối hợp tâng đùi – tâng mu bàn chân xen kẽ.\n+ Luyện tập cá nhân và theo cặp; đếm số lần tâng phối hợp; thi đua giữa các cặp, tổ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Phối hợp hai kĩ thuật giúp giữ cầu lâu hơn và chơi đá cầu tốt hơn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn phối hợp tâng cầu bằng đùi và mu bàn chân.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Bịt mắt bắt dê\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: HS đứng vòng tròn, chọn một bạn bịt mắt bắt dê.\n+ Cách chơi: Bạn bịt mắt di chuyển bắt bạn trong vòng theo tiếng vỗ tay; rèn sự nhanh nhẹn, khéo léo và định hướng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":12,"tiet":1,"bai":"Chủ đề 3: Đá cầu — Bài 4: Di chuyển và tâng cầu; luật chơi đơn giản (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết di chuyển bước đơn để đón và tâng cầu; nắm được luật chơi đá cầu đơn giản.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện di chuyển bước đơn để tâng cầu và trò chơi đá cầu đơn giản.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV hướng dẫn di chuyển bước đơn sang trái/phải, trước/sau để đón cầu và tâng cầu.\n+ Giới thiệu luật chơi đá cầu đơn giản (tâng cầu qua lại, không để cầu rơi).\n+ Luyện tập di chuyển – tâng cầu theo cặp.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Di chuyển đúng giúp đón cầu và tâng cầu dễ dàng hơn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn di chuyển và tâng cầu theo cặp.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":12,"tiet":2,"bai":"Chủ đề 3: Đá cầu — Bài 4: Trò chơi vận dụng đá cầu (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng được kĩ thuật đã học vào trò chơi đá cầu; tham gia thi tâng cầu cá nhân, đồng đội.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cầu đá, khăn; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện vận dụng kĩ thuật đá cầu vào trò chơi và thi tâng cầu.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức thi tâng cầu cá nhân (đếm số lần) và tâng cầu đồng đội (chuyền cầu không rơi).\n+ Tổ chức chơi đá cầu theo cặp/nhóm nhỏ; GV nhận xét, đánh giá tiến bộ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em có thể chơi đá cầu trong giờ ra chơi để rèn luyện sức khỏe và sự khéo léo.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn thi tâng cầu và chơi đá cầu.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Bịt mắt bắt dê\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: HS đứng vòng tròn, chọn một bạn bịt mắt bắt dê.\n+ Cách chơi: Bạn bịt mắt di chuyển bắt bạn trong vòng theo tiếng vỗ tay; rèn sự nhanh nhẹn, khéo léo và định hướng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":13,"tiet":1,"bai":"Chủ đề 4: Thể thao tự chọn (Bóng) — Bài 1: Làm quen với bóng, tung và bắt bóng (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết cách cầm bóng, tung và bắt bóng bằng hai tay; phối hợp tay – mắt khi bắt bóng.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Giữ gìn dụng cụ; nhường nhịn, hợp tác khi tập luyện với bóng.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng cho mỗi cặp/nhóm; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện làm quen với bóng, cách cầm bóng, tung và bắt bóng bằng hai tay.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV giới thiệu quả bóng, cách cầm bóng bằng hai tay.\n+ Tập tung bóng lên cao và bắt bóng bằng hai tay; tập tung – bắt bóng theo cặp.\n+ GV hướng dẫn khép các ngón, đón bóng bằng hai tay, giữ thăng bằng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là cách cầm, tung và bắt bóng bằng hai tay.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn tung và bắt bóng bằng hai tay.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":13,"tiet":2,"bai":"Chủ đề 4: Bóng — Bài 1: Tung và bắt bóng theo cặp (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được tung và bắt bóng qua lại theo cặp, nhóm ở cự li gần; phối hợp ăn ý với bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng cho mỗi cặp/nhóm; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện tung và bắt bóng qua lại theo cặp, nhóm.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn tung và bắt bóng cá nhân.\n+ Luyện tập tung – bắt bóng theo cặp ở cự li gần rồi tăng dần cự li; luyện theo nhóm ba, chuyền bóng vòng tròn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Tung – bắt bóng theo cặp cần phối hợp nhịp nhàng và quan sát bạn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn tung và bắt bóng theo cặp, nhóm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":14,"tiet":1,"bai":"Chủ đề 4: Bóng — Bài 2: Ném bóng trúng đích (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được kĩ thuật ném bóng/túi cát trúng đích cố định; phối hợp tay – mắt, ước lượng khoảng cách.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng/túi cát, đích; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật ném bóng (túi cát) trúng đích cố định.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: đứng chân trước chân sau, tay thuận cầm bóng đưa ra sau.\n+ Ném: chuyển trọng tâm ra trước, vung tay ném bóng về đích, mắt nhìn theo bóng.\n+ Tập ném vào đích gần rồi tăng dần khoảng cách; GV sửa tư thế và hướng ném.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật ném bóng trúng đích cố định.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn ném bóng trúng đích.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":14,"tiet":2,"bai":"Chủ đề 4: Bóng — Bài 2: Ném bóng trúng đích (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Nâng cao độ chính xác khi ném bóng trúng đích; tham gia thi ném bóng đồng đội.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng/túi cát, đích; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện ném bóng trúng đích (ôn luyện, nâng cao độ chính xác).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn kĩ thuật ném, chú ý sửa hướng và lực ném.\n+ Luyện tập theo tổ; tổ chức thi ném bóng trúng đích đồng đội, ghi điểm cho mỗi lượt trúng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Ném chính xác cần luyện tập đều đặn, kiểm soát lực và hướng ném.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn thi ném bóng trúng đích đồng đội.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":15,"tiet":1,"bai":"Chủ đề 4: Bóng — Bài 3: Ném bóng xa (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được kĩ thuật ném bóng đi xa; phối hợp toàn thân, dùng sức hợp lí.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng/túi cát; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật ném bóng đi xa.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: đứng chân trước chân sau, tay thuận cầm bóng.\n+ Ném xa: đưa bóng ra sau, xoay hông, chuyển trọng tâm và vung tay mạnh ném bóng đi xa theo hướng chếch lên.\n+ GV hướng dẫn phối hợp chân – hông – tay; tập ném vào khu vực an toàn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật ném bóng đi xa, cần phối hợp toàn thân.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn ném bóng đi xa.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":15,"tiet":2,"bai":"Chủ đề 4: Bóng — Bài 3: Ném bóng xa (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Cải thiện thành tích ném bóng xa; biết tự đo và ghi lại kết quả để theo dõi tiến bộ.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng/túi cát, thước dây; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện ném bóng xa (ôn luyện, đo thành tích).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn kĩ thuật ném xa, sửa sai.\n+ Tổ chức đo thành tích ném xa theo tổ; GV kết hợp giới thiệu công cụ số hỗ trợ đo/ghi kết quả (ở phần tích hợp).\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Theo dõi thành tích giúp em thấy sự tiến bộ của bản thân.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn ném bóng xa và đo thành tích.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":16,"tiet":1,"bai":"Chủ đề 4: Bóng — Bài 4: Phối hợp tung – bắt – ném bóng; trò chơi với bóng (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Phối hợp được tung – bắt – ném bóng; vận dụng vào trò chơi vận động với bóng.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng, đích; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện phối hợp tung, bắt và ném bóng trong trò chơi vận động.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn phối hợp tung – bắt – ném bóng theo cặp, nhóm.\n+ Tổ chức trò chơi vận động với bóng (chuyền – bắt – ném vào đích) theo tổ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Phối hợp các kĩ thuật giúp em chơi các trò chơi và môn thể thao với bóng tốt hơn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn phối hợp tung – bắt – ném bóng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":16,"tiet":2,"bai":"Chủ đề 4: Bóng — Bài 4: Vận dụng kĩ thuật với bóng vào trò chơi tập thể (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng tổng hợp các kĩ thuật với bóng; tham gia trò chơi tập thể đoàn kết, an toàn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng, đích; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện vận dụng tổng hợp kĩ thuật với bóng vào trò chơi tập thể.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức trò chơi tập thể vận dụng tổng hợp kĩ thuật với bóng, thi đua giữa các tổ.\n+ GV nhận xét, đánh giá sự tiến bộ và tinh thần hợp tác của HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em có thể chơi các trò chơi với bóng cùng bạn bè trong giờ ra chơi, đảm bảo an toàn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trò chơi tập thể với bóng.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ném trúng đích\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ vạch ném và đặt đích (vòng/rổ/mục tiêu).\n+ Cách chơi: HS lần lượt ném bóng/túi cát trúng đích; đội nhiều lượt trúng hơn là thắng. Rèn sức mạnh và khả năng phối hợp tay – mắt.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":17,"tiet":1,"bai":"ÔN TẬP CUỐI HỌC KÌ I: Hệ thống các nội dung đội hình đội ngũ, bài thể dục với vòng và thể thao tự chọn","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Hệ thống, củng cố và thực hiện thành thạo các nội dung, kĩ thuật đã học; tự đánh giá và điều chỉnh động tác của bản thân và bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Ôn luyện, củng cố toàn bộ nội dung học kì I; chuẩn bị cho tiết kiểm tra đánh giá cuối học kì.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, cầu đá, bóng, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Ôn tập, hệ thống kiến thức","gv":"- Mục tiêu: HS hệ thống, ôn luyện toàn bộ nội dung học kì I (đội hình đội ngũ, bài thể dục với vòng, đá cầu, kĩ thuật với bóng).\n- GV hệ thống toàn bộ nội dung học kì I và nêu tiêu chí đánh giá.\n- GV tổ chức ôn theo trạm: trạm đội hình đội ngũ, trạm bài thể dục với vòng, trạm đá cầu, trạm kĩ thuật với bóng; các tổ luân phiên.\n- GV quan sát, sửa sai, giải đáp thắc mắc; nhắc HS ôn luyện thêm ở nhà để chuẩn bị kiểm tra.","hs":"- HS ôn luyện tích cực theo hướng dẫn của GV và cán sự/tổ trưởng.\n- HS tự nhận xét, nhận xét chéo và điều chỉnh động tác; ghi nhớ những nội dung cần cải thiện."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn các nội dung, kĩ thuật đã học theo tổ, nhóm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Thi đua giữa các tổ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia lớp thành các tổ đều nhau.\n+ Cách chơi: Các tổ lần lượt trình diễn/thi đua các nội dung đã ôn; ban giám khảo (GV và cán sự) chấm theo tiêu chí đúng – đều – đẹp; tổ điểm cao nhất thắng cuộc.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":17,"tiet":2,"bai":"Chủ đề 4: Bóng — Bài 5: Hoàn thiện kĩ năng với bóng, trò chơi tổng hợp (Tiết học)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng thành thạo, phối hợp các kĩ năng tung – bắt – ném bóng; tự tin, đoàn kết trong trò chơi tập thể.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bóng, đích; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện hoàn thiện, vận dụng tổng hợp các kĩ năng với bóng (tung – bắt – ném) qua trò chơi.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn và phối hợp thành thạo tung – bắt – ném bóng theo cặp, nhóm.\n+ Tổ chức trò chơi tổng hợp với bóng theo tổ, tăng dần độ khó; GV nhận xét, đánh giá sự tiến bộ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em vận dụng linh hoạt các kĩ năng với bóng vào trò chơi và hoạt động thể thao.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn hoàn thiện kĩ năng với bóng qua trò chơi.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":18,"tiet":1,"bai":"ÔN TẬP CUỐI HỌC KÌ I: Hoàn thiện, chuẩn bị kiểm tra (Tiết ôn)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Hệ thống, củng cố và thực hiện thành thạo các nội dung, kĩ thuật đã học; tự đánh giá và điều chỉnh động tác của bản thân và bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Hoàn thiện kĩ năng, tự tin trình diễn; hình thành thái độ nghiêm túc, tích cực trong đánh giá.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, cầu đá, bóng; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Ôn tập, hệ thống kiến thức","gv":"- Mục tiêu: HS hoàn thiện các nội dung trọng tâm học kì I, tập trình diễn theo tiêu chí kiểm tra.\n- GV cho HS ôn tập trung vào nội dung sẽ kiểm tra: bài thể dục phát triển chung với vòng và một kĩ thuật thể thao tự chọn (đá cầu hoặc ném bóng).\n- GV hướng dẫn HS tập trình diễn theo nhóm đúng tiêu chí đánh giá; góp ý, sửa sai cho từng HS.\n- GV phổ biến hình thức, tiêu chí kiểm tra cuối học kì I ở tiết sau.","hs":"- HS ôn luyện tích cực theo hướng dẫn của GV và cán sự/tổ trưởng.\n- HS tự nhận xét, nhận xét chéo và điều chỉnh động tác; ghi nhớ những nội dung cần cải thiện."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn các nội dung, kĩ thuật đã học theo tổ, nhóm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Thi đua giữa các tổ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia lớp thành các tổ đều nhau.\n+ Cách chơi: Các tổ lần lượt trình diễn/thi đua các nội dung đã ôn; ban giám khảo (GV và cán sự) chấm theo tiêu chí đúng – đều – đẹp; tổ điểm cao nhất thắng cuộc.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":18,"tiet":2,"bai":"KIỂM TRA, ĐÁNH GIÁ CUỐI HỌC KÌ I","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được các động tác, kĩ thuật đã học theo yêu cầu kiểm tra; thể hiện đúng, đủ nội dung và mức độ đạt được của bản thân.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Tự tin, trung thực khi kiểm tra; thể hiện được kết quả rèn luyện của bản thân trong học kì I.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, vòng thể dục, cầu đá, bóng, phiếu đánh giá; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Kiểm tra, đánh giá","gv":"- Mục tiêu: GV kiểm tra, đánh giá mức độ hoàn thành bài thể dục phát triển chung với vòng và một kĩ thuật thể thao tự chọn.\n- GV nêu nội dung, hình thức và tiêu chí kiểm tra: HS trình diễn bài thể dục phát triển chung với vòng và thực hiện một kĩ thuật thể thao tự chọn.\n- GV tổ chức kiểm tra theo nhóm/cá nhân; quan sát, đánh giá theo ba mức: Hoàn thành tốt – Hoàn thành – Chưa hoàn thành.\n- GV công bố kết quả, nhận xét ưu điểm và hướng khắc phục cho từng HS; động viên HS tiếp tục rèn luyện trong học kì II.","hs":"- HS lắng nghe nội dung, tiêu chí kiểm tra; thực hiện phần kiểm tra nghiêm túc, trung thực, tự tin.\n- HS lắng nghe nhận xét, ghi nhớ ưu điểm và hướng khắc phục để tiếp tục rèn luyện."},{"ten":"3. Phần cơ bản — Củng cố sau kiểm tra","gv":"- GV tổ chức cho HS chưa hoàn thành được thực hiện lại (nếu còn thời gian); động viên, hướng dẫn khắc phục.\n- GV nhắc HS những nội dung cần tiếp tục rèn luyện.","hs":"- HS thực hiện lại (nếu được yêu cầu); lắng nghe và ghi nhớ hướng rèn luyện."},{"ten":"4. Vận dụng — Trò chơi thư giãn","gv":"- GV tổ chức một trò chơi vận động nhẹ nhàng, vui vẻ để HS thư giãn sau kiểm tra; đảm bảo an toàn.","hs":"- HS tham gia trò chơi vui vẻ, đoàn kết, giữ an toàn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu lại video/hình ảnh kĩ thuật chuẩn để HS đối chiếu, tự rút kinh nghiệm sau kiểm tra.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/ghi kết quả để tổng hợp thành tích của lớp một cách trực quan. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":19,"tiet":1,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 1: Động tác vươn thở, động tác tay (nhịp điệu) (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác vươn thở và động tác tay của bài thể dục nhịp điệu đúng nhịp, mềm mại; cảm thụ nhịp điệu âm nhạc.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Cảm nhận vẻ đẹp của vận động kết hợp âm nhạc.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác vươn thở và động tác tay của bài thể dục nhịp điệu (tay không).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác vươn thở — TTCB: đứng thẳng, hai tay thả xuôi.\n  Nhịp 1: bước chân, hai tay đưa sang ngang – lên cao, hít sâu. Nhịp 2: hạ tay, thở ra. Nhịp 3–4: như 1–2. Nhịp 5–8: đổi chân.\n+ Động tác tay — Nhịp 1: hai tay đưa ra trước. Nhịp 2: dang ngang. Nhịp 3: lên cao. Nhịp 4: về TTCB. Nhịp 5–8: như 1–4, kết hợp nhún theo nhịp.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Bài thể dục nhịp điệu thực hiện mềm mại, uyển chuyển theo nhịp nhạc.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác vươn thở và tay (nhịp điệu).\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":19,"tiet":2,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 1: Động tác chân, động tác lườn (nhịp điệu) (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác chân, động tác lườn theo nhịp điệu; phối hợp mềm mại, đúng nhịp.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác chân và động tác lườn của bài thể dục nhịp điệu.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác chân — Nhịp 1: khuỵu gối, hai tay đưa ra trước. Nhịp 2: đứng thẳng, tay lên cao. Nhịp 3: khuỵu gối. Nhịp 4: về TTCB. Nhịp 5–8: đổi bên.\n+ Động tác lườn — Nhịp 1: bước chân, tay lên cao. Nhịp 2: nghiêng lườn. Nhịp 3: thẳng người. Nhịp 4: về TTCB. Nhịp 5–8: đổi bên.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Các động tác nhịp điệu cần thực hiện đúng nhịp, biên độ rộng, mềm mại.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác chân và lườn (nhịp điệu).\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":20,"tiet":1,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 2: Động tác bụng, động tác toàn thân (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác bụng, toàn thân theo nhịp điệu; phối hợp nhịp nhàng với nhạc.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác bụng và động tác toàn thân của bài thể dục nhịp điệu.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác bụng — Nhịp 1: tay lên cao, ưỡn nhẹ. Nhịp 2: gập thân, tay chạm mũi chân. Nhịp 3: về nhịp 1. Nhịp 4: về TTCB. Nhịp 5–8: như 1–4.\n+ Động tác toàn thân — Nhịp 1: bước chân, khuỵu gối, tay ra trước. Nhịp 2: đứng thẳng, tay lên cao. Nhịp 3: gập thân. Nhịp 4: về TTCB. Nhịp 5–8: đổi chân.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác bụng và toàn thân phối hợp nhiều nhóm cơ, thực hiện theo nhịp nhạc.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác bụng và toàn thân (nhịp điệu).\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":20,"tiet":2,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 2: Động tác nhảy, động tác điều hòa (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được động tác nhảy, điều hòa theo nhịp điệu; biết thả lỏng sau vận động.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện động tác nhảy và động tác điều hòa của bài thể dục nhịp điệu.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Động tác nhảy — bật nhảy tách – khép chân kết hợp vung tay theo nhịp nhạc.\n+ Động tác điều hòa — hai tay đưa lên nhẹ nhàng, hít vào; hạ tay thả lỏng, thở ra; thực hiện chậm, êm.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Động tác nhảy tạo hứng khởi; động tác điều hòa giúp cơ thể trở lại bình thường.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn động tác nhảy và điều hòa (nhịp điệu).\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":21,"tiet":1,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 3: Hoàn thiện bài thể dục nhịp điệu (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện liên hoàn, đúng nhịp bài thể dục nhịp điệu theo nhạc; phối hợp đều trong nhóm.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện hoàn thiện và tập liên hoàn bài thể dục nhịp điệu theo nhạc.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho cả lớp tập liên hoàn các động tác của bài thể dục nhịp điệu theo nhạc.\n+ Chia nhóm luyện tập, chú ý đồng đều, đúng nhịp; GV sửa sai.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Bài thể dục nhịp điệu giúp cơ thể khỏe, mềm dẻo và cảm thụ âm nhạc.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn liên hoàn bài thể dục nhịp điệu theo nhạc.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Người thừa thứ ba\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":21,"tiet":2,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 3: Trình diễn bài thể dục nhịp điệu theo nhóm (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Trình diễn được bài thể dục nhịp điệu theo nhóm; tự tin, phối hợp ăn ý với bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện trình diễn bài thể dục nhịp điệu theo nhóm, tổ.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho các nhóm luyện tập và trình diễn bài thể dục nhịp điệu theo nhạc.\n+ Các nhóm nhận xét chéo; GV đánh giá, biểu dương nhóm thực hiện đều, đẹp.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em có thể biểu diễn bài thể dục nhịp điệu trong các hoạt động của trường, lớp.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trình diễn bài thể dục nhịp điệu.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":22,"tiet":1,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 4: Bài tập phát triển thể lực và sự phối hợp (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được bài tập phát triển thể lực kết hợp nhịp điệu; phối hợp tay – chân nhịp nhàng.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị phát nhạc (nếu có); máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện bài tập phát triển thể lực kết hợp nhịp điệu, phối hợp vận động.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ Bài tập 1: Bật nhảy tại chỗ kết hợp vỗ tay theo nhịp; 20–25 lần, lặp 2 lần.\n+ Bài tập 2: Di chuyển bước phối hợp tay – chân theo nhịp đếm; rèn sự phối hợp và khéo léo.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Kết hợp thể lực với nhịp điệu giúp vận động vừa khỏe vừa nhịp nhàng.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bài tập thể lực kết hợp nhịp điệu.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":22,"tiet":2,"bai":"Chủ đề 5: Bài thể dục nhịp điệu — Bài 4: Vận dụng, tổ chức thi đua nhịp điệu (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng bài thể dục nhịp điệu vào thi đua tập thể; đoàn kết, tự tin trình diễn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, loa/thiết bị, cờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện vận dụng bài thể dục nhịp điệu, tổ chức thi đua giữa các tổ.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức thi trình diễn bài thể dục nhịp điệu giữa các tổ theo tiêu chí đều – đúng – đẹp.\n+ GV nhận xét, đánh giá, biểu dương và động viên các tổ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Thi đua nhịp điệu giúp lớp thêm gắn bó, rèn sự tự tin và tinh thần tập thể.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn thi đua trình diễn nhịp điệu.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Cướp cờ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia hai đội, đặt khăn/cờ ở giữa sân, mỗi em mang số.\n+ Cách chơi: GV gọi số, hai em cùng số chạy lên cướp cờ mang về vạch của đội mình; ai mang được cờ về an toàn ghi điểm cho đội.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":23,"tiet":1,"bai":"Chủ đề 6: Thể thao tự chọn (Nhảy dây) — Bài 1: Làm quen với dây, so dây, quay dây (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết cách chọn dây phù hợp, so dây và quay dây đều tay; phối hợp tay – cổ tay khi quay dây.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Kiên trì luyện tập nhảy dây để rèn sức bền và sự khéo léo.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện cách chọn dây, so dây và quay dây trong nhảy dây cá nhân.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV hướng dẫn chọn dây phù hợp chiều cao, cách cầm và so dây.\n+ Tập quay dây bằng cổ tay (không nhảy), quay đều về trước; tập tung nhịp quay dây.\n+ GV sửa tư thế cầm dây, quay dây.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là cách chọn dây, so dây và quay dây trong nhảy dây.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn chọn dây, so dây và quay dây.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":23,"tiet":2,"bai":"Chủ đề 6: Nhảy dây — Bài 1: Nhảy dây chụm hai chân (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được kĩ thuật nhảy dây chụm hai chân tại chỗ; phối hợp nhịp quay dây với bật nhảy.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật nhảy dây chụm hai chân tại chỗ.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: hai tay cầm dây, dây phía sau.\n+ Quay dây về trước qua đầu, khi dây chạm đất phía trước thì bật nhảy chụm hai chân qua dây; lặp lại liên tục.\n+ GV hướng dẫn nhịp nhàng, bật nhẹ bằng nửa trước bàn chân.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật nhảy dây chụm hai chân tại chỗ.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn nhảy dây chụm hai chân.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":24,"tiet":1,"bai":"Chủ đề 6: Nhảy dây — Bài 2: Nhảy dây chụm hai chân (tăng số lần, nhịp điệu) (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Nhảy dây chụm hai chân liên tục nhiều lần hơn; giữ nhịp đều, phối hợp thở hợp lí.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện nhảy dây chụm hai chân liên tục nhiều lần, giữ nhịp đều.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn nhảy dây chụm hai chân, đếm số lần liên tục.\n+ Hướng dẫn giữ nhịp đều, thở nhịp nhàng; luyện tập cá nhân và thi đua theo cặp.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Nhảy dây nhiều lần cần giữ nhịp đều và kiên trì luyện tập.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn nhảy dây chụm hai chân liên tục.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":24,"tiet":2,"bai":"Chủ đề 6: Nhảy dây — Bài 2: Nhảy dây kiểu chân trước chân sau (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Bước đầu thực hiện được nhảy dây luân phiên chân trước chân sau; phối hợp nhịp quay dây và đổi chân.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật nhảy dây kiểu chân trước chân sau (luân phiên).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV hướng dẫn nhảy dây luân phiên: mỗi vòng quay đổi chân trước – chân sau.\n+ Tập chậm rồi tăng dần tốc độ; GV sửa sai, khích lệ HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật nhảy dây luân phiên chân trước chân sau.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn nhảy dây chân trước chân sau.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":25,"tiet":1,"bai":"Chủ đề 6: Nhảy dây — Bài 3: Trò chơi nhảy dây tập thể (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia được nhảy dây tập thể với dây dài; phối hợp nhịp nhàng với nhóm, biết vào – ra nhịp dây.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây dài, dây nhảy; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện nhảy dây tập thể (dây dài) và phối hợp nhóm.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV hướng dẫn hai bạn quay dây dài, các bạn lần lượt vào nhảy và ra khỏi vòng dây theo nhịp.\n+ Luyện tập theo nhóm; GV nhắc quan sát nhịp dây để vào – ra an toàn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Nhảy dây tập thể cần phối hợp, quan sát nhịp dây để vào – ra đúng lúc.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn nhảy dây tập thể.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":25,"tiet":2,"bai":"Chủ đề 6: Nhảy dây — Bài 3: Thi nhảy dây; bài tập bổ trợ sức bật (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia thi nhảy dây cá nhân, đồng đội; thực hiện bài tập bổ trợ phát triển sức bật.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy, đồng hồ bấm giờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện thi nhảy dây và bài tập bổ trợ phát triển sức bật của chân.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức thi nhảy dây (đếm số lần trong thời gian quy định) cá nhân và đồng đội.\n+ Bài tập bổ trợ: bật cóc, bật tại chỗ, bật xa tại chỗ để phát triển sức bật.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Nhảy dây và bật nhảy giúp phát triển sức bật, sức bền của đôi chân.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn thi nhảy dây và bài tập sức bật.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":26,"tiet":1,"bai":"Chủ đề 6: Nhảy dây — Bài 4: Vận dụng nhảy dây rèn luyện sức khỏe (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng các kiểu nhảy dây vào tập luyện hằng ngày; tự xây dựng bài tập nhảy dây phù hợp.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy cho mỗi HS; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện vận dụng các kiểu nhảy dây đã học vào rèn luyện sức khỏe hằng ngày.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn các kiểu nhảy dây đã học; hướng dẫn tự sắp xếp bài tập nhảy dây (số lần, thời gian) phù hợp sức khỏe.\n+ Luyện tập cá nhân, tự theo dõi số lần và sự tiến bộ.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em có thể nhảy dây mỗi ngày ở nhà để rèn luyện sức khỏe.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn vận dụng nhảy dây rèn luyện sức khỏe.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":26,"tiet":2,"bai":"Chủ đề 6: Nhảy dây — Bài 4: Tổ chức thi đua nhảy dây; phối hợp trò chơi (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia thi đua nhảy dây kết hợp trò chơi; đoàn kết, trung thực, an toàn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy, bóng; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện tổ chức thi đua nhảy dây kết hợp trò chơi vận động.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức thi đua nhảy dây kết hợp trò chơi tiếp sức giữa các tổ.\n+ GV nhận xét, đánh giá sự tiến bộ, tinh thần thi đua và ý thức an toàn của HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Thi đua nhảy dây giúp em vui khỏe, đoàn kết và tự tin hơn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn thi đua nhảy dây kết hợp trò chơi.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Chuyển bóng tiếp sức\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Các đội xếp hàng dọc, em đứng trước cách em đứng sau một khoảng phù hợp.\n+ Cách chơi: Khi có lệnh, em đầu hàng chuyền bóng qua đầu/qua chân/bên sườn lần lượt về cuối hàng rồi ngược lại. Đội hoàn thành trước, không rơi bóng là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":27,"tiet":1,"bai":"ÔN TẬP GIỮA HỌC KÌ II: Bài thể dục nhịp điệu và nhảy dây","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Hệ thống, củng cố và thực hiện thành thạo các nội dung, kĩ thuật đã học; tự đánh giá và điều chỉnh động tác của bản thân và bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Ôn luyện, củng cố và tự đánh giá mức độ hoàn thành các nội dung nửa đầu học kì II; chuẩn bị cho các nội dung tiếp theo.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, nhạc nền, dây nhảy; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Ôn tập, hệ thống kiến thức","gv":"- Mục tiêu: HS hệ thống, ôn luyện bài thể dục nhịp điệu và các kĩ thuật nhảy dây đã học trong nửa đầu học kì II.\n- GV hệ thống các nội dung: bài thể dục nhịp điệu và các kiểu nhảy dây (chụm hai chân, chân trước chân sau, nhảy dây tập thể).\n- GV tổ chức ôn theo trạm; các tổ luân phiên; tổ trưởng điều khiển, GV sửa sai.\n- Các tổ trình diễn, tự nhận xét và nhận xét chéo về mức độ đúng, đều, đẹp.","hs":"- HS ôn luyện tích cực theo hướng dẫn của GV và cán sự/tổ trưởng.\n- HS tự nhận xét, nhận xét chéo và điều chỉnh động tác; ghi nhớ những nội dung cần cải thiện."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn các nội dung, kĩ thuật đã học theo tổ, nhóm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Thi đua giữa các tổ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia lớp thành các tổ đều nhau.\n+ Cách chơi: Các tổ lần lượt trình diễn/thi đua các nội dung đã ôn; ban giám khảo (GV và cán sự) chấm theo tiêu chí đúng – đều – đẹp; tổ điểm cao nhất thắng cuộc.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":27,"tiet":2,"bai":"Chủ đề 7: Thể thao tự chọn (Chạy) — Bài 1: Chạy nhanh (xuất phát cao) (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Biết tư thế xuất phát cao và thực hiện được chạy nhanh cự li ngắn; phối hợp tay – chân khi chạy.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu, vạch/cọc đánh dấu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện tư thế xuất phát cao và kĩ thuật chạy nhanh cự li ngắn.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB xuất phát cao: chân trước chân sau sau vạch, gối hơi khuỵu, thân hơi ngả trước, mắt nhìn thẳng.\n+ Khi có lệnh, đạp chân xuất phát nhanh, đánh tay tự nhiên, chạy bằng nửa trước bàn chân.\n+ GV hướng dẫn phối hợp tay – chân, giữ hướng chạy thẳng.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là tư thế xuất phát cao và kĩ thuật chạy nhanh cự li ngắn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn xuất phát cao và chạy nhanh.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":28,"tiet":1,"bai":"Chủ đề 7: Chạy — Bài 1: Chạy nhanh và trò chơi phát triển sức nhanh (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Cải thiện tốc độ chạy nhanh cự li ngắn; tham gia trò chơi phát triển sức nhanh, phản xạ.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu, đồng hồ bấm giờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện chạy nhanh (ôn luyện) và trò chơi phát triển sức nhanh.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn xuất phát cao và chạy nhanh cự li ngắn (khoảng 15–20m).\n+ Tổ chức trò chơi tiếp sức chạy nhanh giữa các tổ; GV đo thời gian, khích lệ HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Chạy nhanh giúp phát triển sức nhanh; cần chạy đúng kĩ thuật và giữ an toàn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn chạy nhanh và trò chơi tiếp sức.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":28,"tiet":2,"bai":"Chủ đề 7: Chạy — Bài 2: Chạy bền (sức bền) (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được chạy bền cự li phù hợp; biết phân phối sức và điều hòa nhịp thở khi chạy.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu, đồng hồ bấm giờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật chạy bền và cách phân phối sức khi chạy bền.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV hướng dẫn chạy bền với tốc độ đều, thở nhịp nhàng (2 bước hít – 2 bước thở).\n+ Tập chạy bền quanh sân với cự li/thời gian tăng dần theo sức khỏe.\n+ GV nhắc HS không gắng sức quá mức, lắng nghe cơ thể.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật chạy bền và cách phân phối sức, điều hòa nhịp thở.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn chạy bền và điều hòa nhịp thở.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":29,"tiet":1,"bai":"Chủ đề 7: Chạy — Bài 2: Chạy bền kết hợp đi bộ (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được chạy bền kết hợp đi bộ; nâng dần sức bền, tự theo dõi nhịp tim, sức khỏe.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, đồng hồ bấm giờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện chạy bền kết hợp đi bộ để nâng dần sức bền.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS chạy bền kết hợp đi bộ theo chu kì (chạy nhẹ – đi bộ – chạy nhẹ), tăng dần cự li.\n+ Hướng dẫn HS tự cảm nhận nhịp thở, nhịp tim; nghỉ ngơi và uống nước hợp lí.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Chạy bền kết hợp đi bộ giúp nâng dần sức bền một cách an toàn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn chạy bền kết hợp đi bộ.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":29,"tiet":2,"bai":"Chủ đề 7: Bật nhảy — Bài 3: Bật xa tại chỗ (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được kĩ thuật bật xa tại chỗ; phối hợp tay – chân và dùng sức hợp lí.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, thước dây, đệm tiếp đất/bãi cát; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật bật xa tại chỗ.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: đứng hai chân rộng bằng vai sau vạch, khuỵu gối, đánh tay ra sau.\n+ Bật: đánh tay ra trước – lên cao, đạp mạnh hai chân bật xa về trước, tiếp đất bằng hai chân, khuỵu gối giảm chấn.\n+ GV hướng dẫn phối hợp tay – chân, tiếp đất an toàn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật bật xa tại chỗ, cần phối hợp tay – chân và tiếp đất an toàn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bật xa tại chỗ.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":30,"tiet":1,"bai":"Chủ đề 7: Bật nhảy — Bài 3: Bật xa tại chỗ (đo thành tích) (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Cải thiện thành tích bật xa; biết tự đo, ghi lại kết quả để theo dõi sự tiến bộ.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, thước dây, đệm tiếp đất; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện bật xa tại chỗ (ôn luyện, đo và ghi thành tích).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS ôn bật xa tại chỗ, sửa sai kĩ thuật.\n+ Tổ chức đo thành tích bật xa theo tổ; kết hợp giới thiệu công cụ số đo/ghi kết quả (phần tích hợp).\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Theo dõi thành tích bật xa giúp em thấy sự tiến bộ và cố gắng hơn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bật xa tại chỗ và đo thành tích.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":30,"tiet":2,"bai":"Chủ đề 7: Bật nhảy — Bài 4: Bật cao, bật nhảy phối hợp (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được bật cao tại chỗ và bật nhảy phối hợp; phát triển sức bật của chân.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, mốc chạm, đệm tiếp đất; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện kĩ thuật bật cao tại chỗ và bật nhảy phối hợp.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ TTCB: đứng hai chân rộng bằng vai, khuỵu gối, đánh tay ra sau.\n+ Bật cao: đánh tay lên cao, đạp mạnh hai chân bật thẳng lên cao, với tay chạm mốc; tiếp đất khuỵu gối.\n+ Tập bật nhảy phối hợp: chạy đà nhẹ – bật cao chạm mốc.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Đây là kĩ thuật bật cao và bật nhảy phối hợp phát triển sức bật.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bật cao và bật nhảy phối hợp.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":31,"tiet":1,"bai":"Chủ đề 7: Bật nhảy — Bài 4: Vận dụng chạy – bật nhảy vào trò chơi (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng phối hợp chạy và bật nhảy vào trò chơi tổng hợp; đoàn kết, an toàn, tích cực.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ hiệu, mốc, đệm tiếp đất; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện vận dụng chạy và bật nhảy vào trò chơi vận động tổng hợp.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức trò chơi tổng hợp: chạy nhanh – bật xa – bật cao chạm mốc theo tổ (tiếp sức).\n+ GV nhận xét, đánh giá sự tiến bộ và ý thức an toàn của HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em có thể vận dụng chạy, bật nhảy vào các trò chơi và hoạt động thể thao hằng ngày.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trò chơi tổng hợp chạy – bật nhảy.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":31,"tiet":2,"bai":"Chủ đề 7: Chạy – Bật nhảy — Bài 5: Bài tập bổ trợ và trò chơi phát triển sức mạnh chân (Tiết học)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được bài tập bổ trợ phát triển sức mạnh chân; vận dụng vào trò chơi vận động an toàn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, bục thấp, cờ hiệu, đệm; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện bài tập bổ trợ và trò chơi phát triển sức mạnh, sức bật của chân.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS thực hiện bài tập bổ trợ: bật cóc ngắn, bật bục thấp, lò cò một chân (mức nhẹ, an toàn).\n+ Tổ chức trò chơi tiếp sức kết hợp bật nhảy theo tổ; GV nhắc lượng vận động vừa sức, tiếp đất an toàn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Các bài tập bổ trợ giúp đôi chân khỏe và bật cao, bật xa tốt hơn.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bài tập bổ trợ phát triển sức mạnh chân.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":32,"tiet":1,"bai":"Chủ đề 8: Trò chơi vận động và phát triển thể lực — Bài 1: Trò chơi rèn sức nhanh, khéo léo (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia được các trò chơi vận động rèn sức nhanh, khéo léo; phối hợp vận động linh hoạt, an toàn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cọc, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện các trò chơi vận động rèn sức nhanh và sự khéo léo.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức các trò chơi rèn sức nhanh, khéo léo: \"Ai nhanh hơn\", \"Luồn cọc tiếp sức\", \"Đổi chỗ theo tín hiệu\".\n+ GV phổ biến luật, làm mẫu, điều khiển và đảm bảo an toàn cho HS.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Các trò chơi vận động giúp em nhanh nhẹn, khéo léo và vui khỏe.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trò chơi rèn sức nhanh, khéo léo.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":32,"tiet":2,"bai":"Chủ đề 8: Trò chơi vận động — Bài 1: Trò chơi rèn sức mạnh, sức bền (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia được các trò chơi rèn sức mạnh, sức bền; biết tự điều chỉnh lượng vận động vừa sức.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây kéo co, cờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện các trò chơi và bài tập rèn sức mạnh, sức bền.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức trò chơi \"Kéo co\", \"Cõng bạn tiếp sức\" (mức nhẹ, an toàn) rèn sức mạnh; kết hợp bài tập chạy bền nhẹ rèn sức bền.\n+ GV nhắc HS tập vừa sức, nghỉ ngơi hợp lí, đảm bảo an toàn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Trò chơi rèn sức mạnh, sức bền giúp cơ thể khỏe hơn; cần tập vừa sức.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trò chơi rèn sức mạnh, sức bền.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Cướp cờ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia hai đội, đặt khăn/cờ ở giữa sân, mỗi em mang số.\n+ Cách chơi: GV gọi số, hai em cùng số chạy lên cướp cờ mang về vạch của đội mình; ai mang được cờ về an toàn ghi điểm cho đội.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":33,"tiet":1,"bai":"Chủ đề 8: Trò chơi vận động — Bài 2: Trò chơi dân gian rèn luyện sức khỏe (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia được một số trò chơi dân gian vận động; giữ gìn và yêu thích trò chơi dân gian.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Yêu thích, giữ gìn trò chơi dân gian của quê hương.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, khăn bịt mắt; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện trò chơi dân gian vận động rèn luyện sức khỏe và tinh thần tập thể.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV giới thiệu và tổ chức các trò chơi dân gian vận động: \"Rồng rắn lên mây\", \"Mèo đuổi chuột\", \"Bịt mắt bắt dê\".\n+ GV phổ biến cách chơi, luật chơi, làm mẫu; điều khiển và đảm bảo an toàn.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Trò chơi dân gian vừa rèn sức khỏe vừa giúp em hiểu và giữ gìn nét đẹp truyền thống.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trò chơi dân gian vận động.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Bịt mắt bắt dê\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: HS đứng vòng tròn, chọn một bạn bịt mắt bắt dê.\n+ Cách chơi: Bạn bịt mắt di chuyển bắt bạn trong vòng theo tiếng vỗ tay; rèn sự nhanh nhẹn, khéo léo và định hướng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":33,"tiet":2,"bai":"Chủ đề 8: Trò chơi vận động — Bài 2: Bài tập phát triển thể lực tổng hợp (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được bài tập phát triển thể lực tổng hợp; tự theo dõi, đánh giá sức khỏe của bản thân.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cọc, cờ hiệu, đồng hồ bấm giờ; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện bài tập phát triển thể lực tổng hợp (nhanh – mạnh – bền – khéo).\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV tổ chức chuỗi bài tập tổng hợp theo trạm: bật nhảy (mạnh) – chạy nhanh (nhanh) – chạy bền nhẹ (bền) – luồn cọc (khéo).\n+ HS luân phiên qua các trạm; GV nhắc lượng vận động vừa sức, nghỉ hồi tĩnh giữa các trạm.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Bài tập tổng hợp giúp cơ thể phát triển toàn diện; cần lắng nghe cơ thể mình.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn bài tập thể lực tổng hợp theo trạm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Ô tô về bến\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Kẻ sân chơi, chia lớp thành các đội.\n+ Cách chơi: HS di chuyển theo hiệu lệnh (đèn xanh chạy, đèn đỏ dừng); ai sai hiệu lệnh bị mời ra ngoài. Rèn phản xạ và khả năng phối hợp.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":34,"tiet":1,"bai":"Chủ đề 8: Trò chơi vận động — Bài 3: Trò chơi dân gian địa phương và rèn luyện sức khỏe (Tiết 1)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Tham gia được một số trò chơi dân gian của địa phương; yêu thích, giữ gìn và biết cách tổ chức trò chơi cùng bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Yêu quý và giữ gìn trò chơi dân gian của quê hương.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, cờ, dây kéo co, bao bố; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện một số trò chơi dân gian địa phương giúp rèn luyện sức khỏe và tinh thần tập thể.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV giới thiệu, tổ chức một số trò chơi dân gian gắn với địa phương (kéo co, nhảy bao bố, cướp cờ, ô ăn quan vận động…).\n+ GV phổ biến cách chơi, luật chơi, làm mẫu; điều khiển và đảm bảo an toàn; khuyến khích HS tự tổ chức chơi.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Trò chơi dân gian vừa vui khỏe vừa giúp em giữ gìn nét đẹp văn hóa quê hương.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn trò chơi dân gian địa phương.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Cướp cờ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia hai đội, đặt khăn/cờ ở giữa sân, mỗi em mang số.\n+ Cách chơi: GV gọi số, hai em cùng số chạy lên cướp cờ mang về vạch của đội mình; ai mang được cờ về an toàn ghi điểm cho đội.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV trình chiếu tranh/ảnh kĩ thuật số phân tách từng nhịp động tác để HS quan sát rõ yếu lĩnh, đối chiếu với động tác của mình.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/đếm số lần trên điện thoại để đo và ghi kết quả bài tập phát triển thể lực, giúp HS theo dõi sự tiến bộ. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":34,"tiet":2,"bai":"Chủ đề 8: Trò chơi vận động — Bài 3: Ôn luyện tổng hợp, vận dụng rèn luyện sức khỏe hằng ngày (Tiết 2)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Vận dụng linh hoạt các động tác, kĩ thuật, trò chơi đã học để tự rèn luyện sức khỏe; hình thành thói quen tập luyện thường xuyên.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, dây nhảy, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Người thừa thứ ba\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Hình thành kiến thức (Kiến thức mới)","gv":"- Mục tiêu: HS nắm được cách thực hiện vận dụng các nội dung đã học vào rèn luyện sức khỏe hằng ngày và xây dựng thói quen tập luyện.\n- GV cho HS quan sát tranh ảnh/video kĩ thuật, sau đó làm mẫu kết hợp phân tích, giảng giải kĩ thuật (GV hô nhịp thật chậm để HS quan sát):\n+ GV cho HS luyện tập tổng hợp các nội dung yêu thích (bài thể dục nhịp điệu, nhảy dây, bật nhảy, trò chơi).\n+ GV hướng dẫn HS tự xây dựng một bài tập/thói quen rèn luyện sức khỏe hằng ngày phù hợp bản thân.\n- GV đặt câu hỏi gợi mở để HS nhận biết yếu lĩnh động tác; gọi 2–3 HS xung phong tập thử theo mẫu.\n- GV hô chậm và tập cùng cả lớp, chú ý quan sát, sửa sai cho HS; tăng dần tần số nhịp cho tới khi các em tập cơ bản đúng.\n- GV cùng HS nhận xét, đánh giá, động viên, cổ vũ những HS thực hiện tốt.","hs":"- HS quan sát tranh ảnh/video và GV làm mẫu; lắng nghe phân tích kĩ thuật.\n- HS trả lời câu hỏi của GV: + Em duy trì thói quen tập luyện mỗi ngày để cơ thể luôn khỏe mạnh.\n- HS xung phong tập thử, cả lớp tập theo mẫu (2 lần 8 nhịp), tự sửa sai và ghi nhớ yếu lĩnh động tác."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn vận dụng rèn luyện sức khỏe hằng ngày.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Nhảy lướt sóng\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Mỗi đội một đoạn dây ~2m, xếp hàng dọc.\n+ Cách chơi: Cặp tạo sóng cầm hai đầu dây di chuyển dọc hàng, các bạn bật nhảy hai chân lướt sóng, không để dây chạm chân. Đội xong trước, đúng luật là thắng.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng đếm nhịp (metronome) trên điện thoại để giữ nhịp đều khi cả lớp tập động tác/bài thể dục. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":35,"tiet":1,"bai":"ÔN TẬP CUỐI NĂM: Hoàn thiện, chuẩn bị kiểm tra (Tiết ôn)","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Hệ thống, củng cố và thực hiện thành thạo các nội dung, kĩ thuật đã học; tự đánh giá và điều chỉnh động tác của bản thân và bạn.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Hoàn thiện kĩ năng, tự tin trình diễn; hình thành thái độ nghiêm túc, tích cực trong đánh giá.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, nhạc nền, dây nhảy, cờ hiệu; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Ôn tập, hệ thống kiến thức","gv":"- Mục tiêu: HS hoàn thiện các nội dung trọng tâm cả năm, tập trình diễn theo tiêu chí kiểm tra cuối năm.\n- GV cho HS ôn tập trung vào nội dung sẽ kiểm tra: bài thể dục nhịp điệu và một kĩ thuật thể thao tự chọn (nhảy dây, chạy nhanh hoặc bật xa).\n- GV hướng dẫn HS tập trình diễn theo nhóm đúng tiêu chí đánh giá; góp ý, sửa sai cho từng HS.\n- GV phổ biến hình thức, tiêu chí kiểm tra cuối năm ở tiết sau.","hs":"- HS ôn luyện tích cực theo hướng dẫn của GV và cán sự/tổ trưởng.\n- HS tự nhận xét, nhận xét chéo và điều chỉnh động tác; ghi nhớ những nội dung cần cải thiện."},{"ten":"3. Phần cơ bản — Luyện tập","gv":"- Mục tiêu: HS luyện tập nhuần nhuyễn các nội dung, kĩ thuật đã học theo tổ, nhóm.\n- GV tổ chức luyện tập theo trình tự: đồng loạt cả lớp → theo cặp (hai bạn cạnh nhau tập và nhận xét cho nhau) → theo tổ (tổ trưởng vừa hô vừa tập cùng các bạn).\n- GV quan sát, sửa lỗi sai chung; với HS tiếp thu chậm, GV hướng dẫn luyện tập ở tốc độ chậm, kết hợp sửa động tác.\n- GV tổ chức cho các tổ thi đua, biểu dương tổ thực hiện đúng, đều, đẹp.","hs":"- HS luyện tập theo hình thức đồng loạt, theo cặp và theo tổ dưới sự điều khiển của cán sự/tổ trưởng.\n- HS quan sát, nhận xét và sửa sai cho bạn; tích cực tham gia thi đua giữa các tổ."},{"ten":"4. Vận dụng — Trò chơi vận động","gv":"- Mục tiêu: Rèn luyện sự khéo léo, nhanh nhẹn, sức mạnh; giáo dục tinh thần tập thể, tính đoàn kết; vận dụng kiến thức đã học.\n- GV tổ chức trò chơi \"Thi đua giữa các tổ\": chia đội, phổ biến cách chơi, luật chơi và làm mẫu.\n+ Chuẩn bị: Chia lớp thành các tổ đều nhau.\n+ Cách chơi: Các tổ lần lượt trình diễn/thi đua các nội dung đã ôn; ban giám khảo (GV và cán sự) chấm theo tiêu chí đúng – đều – đẹp; tổ điểm cao nhất thắng cuộc.\n- GV điều khiển trò chơi, đảm bảo an toàn, nhận xét, tuyên dương đội thắng cuộc và động viên các đội.","hs":"- HS lắng nghe cách chơi, luật chơi; tham gia trò chơi tích cực, trung thực, đoàn kết và giữ an toàn.\n- HS cổ vũ bạn, chấp hành hiệu lệnh của GV."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu video kĩ thuật động tác mẫu (từ học liệu số/kênh đã kiểm duyệt) trên màn hình cho HS quan sát, so sánh với động tác vừa tập, nhận ra chỗ cần điều chỉnh.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng đồng hồ thông minh/ứng dụng đếm bước, đo nhịp tim minh họa cho HS thấy sự thay đổi của cơ thể trước và sau vận động. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]},
{"lop":4,"mon":"Giáo dục thể chất","tuan":35,"tiet":2,"bai":"KIỂM TRA, ĐÁNH GIÁ CUỐI NĂM HỌC","yccd":"1. Năng lực đặc thù (thể chất)\n- Chăm sóc sức khỏe: Biết và thực hiện vệ sinh sân tập, vệ sinh cá nhân trước, trong và sau khi tập luyện; nhận biết và phòng tránh những yếu tố gây mất an toàn khi tập luyện môn Giáo dục thể chất.\n- Vận động cơ bản: Thực hiện được các động tác, kĩ thuật đã học theo yêu cầu kiểm tra; thể hiện đúng, đủ nội dung và mức độ đạt được của bản thân.\n- Hoạt động thể dục thể thao: Biết quan sát tranh ảnh, video và động tác làm mẫu của GV để tập luyện; bước đầu biết điều khiển tổ, nhóm tập luyện và giúp đỡ bạn; tham gia tích cực trò chơi vận động và bài tập phát triển thể lực; hoàn thành lượng vận động của bài tập.\n2. Năng lực chung\n- Tự chủ và tự học: Chủ động xem trước động tác trong SGK/học liệu số; tự giác luyện tập và tự sửa sai động tác.\n- Giao tiếp và hợp tác: Biết phối hợp với bạn khi tập luyện theo cặp, nhóm, tổ; biết lắng nghe, chia sẻ ý kiến và sửa sai cho nhau.\n- Giải quyết vấn đề và sáng tạo: Phát hiện lỗi sai thường mắc và tìm cách khắc phục; vận dụng động tác đã học vào hoạt động tập thể.\n3. Phẩm chất\n- Chăm chỉ: Nghiêm túc, tích cực, tự giác trong tập luyện và hoạt động tập thể; hình thành thói quen thường xuyên tập luyện thể dục thể thao.\n- Trách nhiệm: Có trách nhiệm với bản thân và tập thể; giữ gìn an toàn, đoàn kết, hòa đồng với mọi người.\n- Tự tin, trung thực khi kiểm tra; thể hiện được kết quả rèn luyện của bản thân trong cả năm học.","dodung":"- Địa điểm: Sân trường (hoặc nhà đa năng) sạch sẽ, bằng phẳng, thoáng mát, đảm bảo an toàn.\n- Giáo viên: còi, đồng hồ bấm giờ, tranh ảnh/video động tác mẫu, kẻ vẽ sân theo nội dung bài, nhạc nền, dây nhảy, cờ hiệu, phiếu đánh giá; máy tính/điện thoại có màn hình để chiếu video mẫu (nếu có điều kiện).\n- Học sinh: trang phục thể thao, giày tập hoặc dép quai hậu; đảm bảo vệ sinh và an toàn trong tập luyện.","hoatdong":[{"ten":"1. Phần mở đầu — Khởi động","gv":"- GV nhận lớp, kiểm tra sĩ số, trang phục, thăm hỏi sức khỏe HS; phổ biến ngắn gọn nội dung, yêu cầu giờ học.\n- GV hướng dẫn HS khởi động chung: chạy nhẹ tại chỗ/quanh sân, xoay các khớp (cổ, cổ tay, cổ chân, vai, hông, gối), ép dây chằng, vỗ tay làm nóng cơ thể.\n- GV tổ chức trò chơi khởi động \"Làm theo hiệu lệnh\" để tăng khả năng phản xạ và tạo hứng thú.\n- GV nhận xét, khích lệ và dẫn dắt vào bài mới.","hs":"- Cán sự lớp tập trung lớp thành hàng, điểm số, báo cáo sĩ số cho GV.\n- HS khởi động các khớp và thực hiện các động tác làm nóng theo hướng dẫn của GV.\n- HS tích cực, hào hứng tham gia trò chơi khởi động; lắng nghe GV giới thiệu bài."},{"ten":"2. Phần cơ bản — Kiểm tra, đánh giá","gv":"- Mục tiêu: GV kiểm tra, đánh giá mức độ hoàn thành bài thể dục nhịp điệu và một kĩ thuật thể thao tự chọn cả năm học.\n- GV nêu nội dung, hình thức và tiêu chí kiểm tra: HS trình diễn bài thể dục nhịp điệu và thực hiện một kĩ thuật thể thao tự chọn (nhảy dây/chạy nhanh/bật xa).\n- GV tổ chức kiểm tra theo nhóm/cá nhân; quan sát, đánh giá theo ba mức: Hoàn thành tốt – Hoàn thành – Chưa hoàn thành.\n- GV công bố kết quả, nhận xét cả năm, khen ngợi tiến bộ; định hướng rèn luyện thể dục thể thao trong hè và năm học tiếp theo.","hs":"- HS lắng nghe nội dung, tiêu chí kiểm tra; thực hiện phần kiểm tra nghiêm túc, trung thực, tự tin.\n- HS lắng nghe nhận xét, ghi nhớ ưu điểm và hướng khắc phục để tiếp tục rèn luyện."},{"ten":"3. Phần cơ bản — Củng cố sau kiểm tra","gv":"- GV tổ chức cho HS chưa hoàn thành được thực hiện lại (nếu còn thời gian); động viên, hướng dẫn khắc phục.\n- GV nhắc HS những nội dung cần tiếp tục rèn luyện.","hs":"- HS thực hiện lại (nếu được yêu cầu); lắng nghe và ghi nhớ hướng rèn luyện."},{"ten":"4. Vận dụng — Trò chơi thư giãn","gv":"- GV tổ chức một trò chơi vận động nhẹ nhàng, vui vẻ để HS thư giãn sau kiểm tra; đảm bảo an toàn.","hs":"- HS tham gia trò chơi vui vẻ, đoàn kết, giữ an toàn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền NLS: Khai thác học liệu số — mức 1 · Nhận biết) GV chiếu lại video/hình ảnh kĩ thuật chuẩn để HS đối chiếu, tự rút kinh nghiệm sau kiểm tra.\n⚠ An toàn: GV thao tác và kiểm soát hoàn toàn thiết bị; HS chỉ quan sát, không tự sử dụng thiết bị; thời lượng xem ngắn, ưu tiên vận động thực tế; nhắc HS giữ khoảng cách, bảo vệ thị giác, không xem thiết bị khi đang vận động.\n- (AI mức 1 — Nhận biết) GV dùng ứng dụng bấm giờ/ghi kết quả để tổng hợp thành tích của lớp một cách trực quan. GV giới thiệu, thao tác và kiểm soát; HS chỉ quan sát, nhận xét, không tự nhập liệu cá nhân.","hs":"- HS quan sát video/hình ảnh kĩ thuật số, tự đối chiếu với động tác mình vừa tập và điều chỉnh khi luyện tập.\n- HS quan sát GV thao tác thiết bị, không tự ý sử dụng.\n- HS quan sát ứng dụng do GV trình chiếu, nêu nhận xét; hiểu công nghệ chỉ là công cụ hỗ trợ luyện tập."},{"ten":"6. Phần kết thúc — Hồi tĩnh","gv":"- GV cho HS thực hiện các động tác thả lỏng, hồi tĩnh: đi lại nhẹ nhàng, rũ tay chân, hít thở sâu.\n- GV cùng HS hệ thống lại nội dung bài học; nhận xét, đánh giá kết quả giờ học theo ba mức: Hoàn thành tốt / Hoàn thành / Chưa hoàn thành; khen ngợi HS tích cực, động viên HS còn nhút nhát.\n- GV giao nhiệm vụ về nhà: ôn lại động tác đã học, tích cực rèn luyện thể dục thể thao; nhắc HS chuẩn bị bài sau.","hs":"- HS thực hiện thả lỏng, hồi tĩnh, điều hòa hô hấp theo hướng dẫn.\n- HS cùng GV hệ thống bài học, lắng nghe nhận xét và ghi nhớ nhiệm vụ về nhà."}]}
];
